function computeErrorBudget(sloTarget, windowMinutes) {
  if (sloTarget <= 0 || sloTarget >= 1) {
    throw new Error(`sloTarget must be between 0 and 1, got: ${sloTarget}`);
  }
  return Math.round(windowMinutes * (1 - sloTarget) * 100) / 100;
}

