function computeConsumedMinutes(failedRequests, totalRequests, elapsedMinutes) {
  if (!(totalRequests > 0)) {
    throw new Error("totalRequests must be greater than 0");
  }
  const failureRatio = failedRequests / totalRequests;
  return Math.round(elapsedMinutes * failureRatio * 100) / 100;
}

